import logging
import re
import sys
import time
from collections import namedtuple
from ute_common_abstract_core.network_elem_identification import UeIdentification
from ta_messaging import message_parser
from ta_messaging.message_sources import message_source_base
from ta_messaging.unparsed_message import UnparsedMessage
from ta_messaging.py3_string import py3_string
import zmq
import json
import pprint


class QxdmMessageSource(message_source_base.MessageSource):
    '''
    Specific message source that implements extracting unparsed messages from zmq socket opened by python server running on UE_PC
    '''
    packet_type_to_hex_map = {
        'LTE RRC OTA Packet': ['0xB0C0'],
    }
    _msg_tuple = namedtuple(typename='Msg_container_tuple', field_names='payload type occurrence_time')
    _ip_port_pattern = re.compile(r'([0-9]+(?:\.[0-9]+){3}):([0-9]+)')

    def __init__(self, queue, id):
        self.ue_id = id
        assert self._ip_port_pattern.match(self.ue_id), "ue_id for id_type=qxdm has to match pattern: <ip>:<port>"
        [self.server_ip, self.server_port] = re.split(':', self.ue_id)
        self.socket = None
        self.poller = None
        self.context = None
        self._get_opened_connection()
        super(QxdmMessageSource, self).__init__(queue)
        self.source_specific_parser = message_parser.QxdmMessageParser()
        self._file_existence_check_interval = 0.1
        self._start_in_separate_thread()

    def _create_ue_owner(self):
        device_id = self.ue_id
        return UeIdentification.from_type_id_pairs(identifiers=[('qxdm', device_id)], specific_for_tool='qxdm')

    def _src_name(self):
        '''
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        '''
        return 'qxdm-ue_{}'.format(self.ue_id)

    def _read(self):
        while self.is_running.is_set():
            data = self._read_data_from_socket()
            if data:
                return data
            time.sleep(0.01)
        return None

    def _read_data_from_socket(self):
        sockets = dict(self.poller.poll(500))
        if self.socket in sockets:
            return py3_string(self.socket.recv_string())
        else:
            return None

    def _get_protocol_data(self):
        while self.is_running.is_set():
            chunk = self._read()
            if chunk is None:
                return None
            all_protocol_data = [json.loads(chunk)]
            rrc_protocol_data = self._filter_rrc_protocol_data(all_protocol_data)

            if len(rrc_protocol_data) > 0:
                return rrc_protocol_data

    def _filter_rrc_protocol_data(self, all_protocol_data):
        rrc_protocol_data = []
        for pdu in all_protocol_data:
            if self._is_packet_given_type(pdu, 'LTE RRC OTA Packet'):
                rrc_protocol_data.append(pdu)
        return rrc_protocol_data

    def _get_packet_data(self, protocol_data):
        msg_types = []
        msg_times = []
        payloads = []
        for pdu in protocol_data:
            msg_type = self._get_message_type(pdu)
            msg_time = self._get_message_time(pdu)
            payload = self._get_message_payload(pdu)
            msg_types.append(msg_type)
            msg_times.append(msg_time)
            payloads.append(payload)
            self.logger.debug('{} After retrieving payload and type: {} {} {}'.format(self, msg_type, msg_time, payload))
        return [QxdmMessageSource._msg_tuple(*record) for record in list(zip(payloads, msg_types, msg_times))]

    def _get_message_payload(self, pdu):
        try:
            return pdu.get("pdu")
        except KeyError:
            self.logger.error('Could not decode message payload. Wrong pdu format {}'.format(pdu))

    def _get_message_time(self, pdu):
        try:
            timestamp = pdu.get('metadata').get("timestamp")
            return self._convert_tuple_to_epoch_time(timestamp)
        except KeyError:
            self.logger.error('Could not decode message time. Wrong pdu format {}'.format(pdu))

    def _get_message_type(self, pdu):
        try:
            return pdu.get('metadata').get("message_type")
        except KeyError:
            self.logger.error('Could not decode message type. Wrong pdu format {}'.format(pdu))

    def _is_packet_given_type(self, packet, desired_type):
        assert desired_type in self.packet_type_to_hex_map
        packet_hex_id = ''
        try:
            packet_hex_id = packet.get('metadata').get("message_hex")
        except (KeyError, AttributeError):
            self.logger.error('Could not decode packet. Wrong pdu format {}'.format(packet))
        if packet_hex_id in self.packet_type_to_hex_map[desired_type]:
            return True
        return False

    def _create_unparsed_message(self, msg_tuple):
        owner = self._create_ue_owner()
        msg_payload = msg_tuple.payload
        message_type = msg_tuple.type
        occurrence_time = msg_tuple.occurrence_time
        (msg, err, debug) = UnparsedMessage.from_msg_type(owner=owner,
                                                          msg_payload=msg_payload,
                                                          message_type_value_str=message_type,
                                                          parser=self.source_specific_parser,
                                                          meta_data_dict={'occurrence_time': occurrence_time})
        if debug:
            self.logger.debug(debug)
        if err:
            self.logger.error(err)
            messaging_logger = logging.getLogger('messaging')
            messaging_logger.error(err)
        return msg

    def _get_unparsed_messages(self, protocol_data):
        msgs = self._get_packet_data(protocol_data)
        return [self._create_unparsed_message(msg) for msg in msgs]

    def _get_socket_opt_function(self, socket):
        if sys.version_info[0] >= 3:
            return socket.setsockopt_string
        else:
            return socket.setsockopt

    def _get_opened_connection(self):
        self.context = zmq.Context()
        self.socket = self.context.socket(zmq.SUB)
        self.poller = zmq.Poller()
        self.socket.connect('tcp://{}:{}'.format(self.server_ip, self.server_port))
        self.poller.register(self.socket, zmq.POLLIN)
        self._get_socket_opt_function(self.socket)(zmq.SUBSCRIBE, '')

    def _close_connection(self):
        self.socket.close()
        self.context.term()

    def start(self):
        '''
        Starts MessageSource infinite loop.
        Infinite loop is composed of parsing data stream, creating UnparsedMessages and sending them to the output queue
        For loop is a generator and can be broken by changed stop condition.
        '''
        self.is_running.set()
        self._source_started.release()
        self.logger.debug('{!r} thread started'.format(self))
        while self.is_running.is_set():
            protocol_data = self._get_protocol_data()
            if protocol_data is None:
                break
            self.logger.trace('%s: << %s' % (self, pprint.pformat(protocol_data)))
            self._put_to_queue(*self._get_unparsed_messages(protocol_data))
        self._main_loop_finished.release()
        self.logger.debug('{!r} thread finished'.format(self))

    @staticmethod
    def _convert_tuple_to_epoch_time(t):
        timestamp = (t.get("year"),
                     t.get("month"),
                     t.get("day"),
                     t.get("hour"),
                     t.get("minute"),
                     t.get("second"),
                     0,
                     0,
                     0,
                     )
        epoch_time = time.mktime(timestamp)
        microseconds = float(t.get("microsecond")) / 1000000
        epoch_str = repr(epoch_time + microseconds)
        return epoch_str
